const classifyTaskDB=[{"w":"Los átomos y el vacío","gen":"Física antigua","n":"Lo único que hay, dijo Demócrito","g":"Siglo V antes de Cristo","t":"Atomismo"},{"w":"La Carta a Meneceo","gen":"Fuente primaria","n":"Cabe entera en una tarde","g":"Escuela de Epicuro","t":"Clásico sólido"},{"w":"De rerum natura","gen":"Fuente primaria","n":"Física en verso, seis libros","g":"Roma, siglo I antes de Cristo","t":"Clásico sólido y literatura"},{"w":"El giro (Greenblatt)","gen":"Divulgación","n":"El hallazgo del manuscrito en 1417","g":"Historia moderna","t":"Divulgación con inflado"},{"w":"El tetrafármaco","gen":"Herramienta","n":"Cuatro frascos contra dos miedos","g":"Escuela de Epicuro","t":"Medicina filosófica"},{"w":"El clinamen","gen":"Hipótesis antigua","n":"Desviación mínima del átomo","g":"De rerum natura, libro II","t":"Intento de salvar la libertad"},{"w":"El deseo sin límite","gen":"Diagnóstico","n":"Nunca se llena, y por eso vende","g":"La tienda y la red","t":"El anzuelo"},{"w":"La doxografía","gen":"Transmisión","n":"Resume libros perdidos","g":"Antigüedad tardía","t":"Segunda mano declarada"},{"w":"Diógenes Laercio, libro X","gen":"Fuente antigua","n":"Preserva las cartas de Epicuro","g":"Vidas de los filósofos ilustres","t":"El archivero del programa"},{"w":"El aviso del huracán","gen":"Mecanismo","n":"Explica y prepara, no amenaza","g":"La casa, hoy","t":"Miedo que se trabaja"}];
const completeTaskDB=[{"s":"Leucipo y Demócrito propusieron átomos y ___.","opts":["vacío","fuego","números"],"ans":"vacío"},{"s":"Epicuro convirtió la física en ___.","opts":["medicina","negocio","poesía"],"ans":"medicina"},{"s":"Los dos miedos: los dioses y la ___.","opts":["muerte","pobreza","noche"],"ans":"muerte"},{"s":"Lucrecio escribió la física en ___.","opts":["verso","tablas","cartas"],"ans":"verso"},{"s":"La miel del borde hace pasar la ___.","opts":["medicina","tarea","tarde"],"ans":"medicina"},{"s":"El deseo sin límite es el ___.","opts":["anzuelo","premio","motor"],"ans":"anzuelo"},{"s":"El atomismo como programa sigue ___.","opts":["vivo","preso","igual"],"ans":"vivo"},{"s":"Demócrito llega por fragmentos y ___.","opts":["doxografía","fotos","actas"],"ans":"doxografía"}];
const explainQuestions=[{"q":"¿Por qué un poema de física quita el miedo? Explícalo en cinco minutos, como pide el compendio.","ans":"Porque los miedos grandes (el castigo del cielo, la muerte) se alimentan de no saber cómo funcionan las cosas: donde no hay mecanismo, cualquiera puede poner una amenaza y cobrarla. De rerum natura enseña, verso a verso, de qué está hecho lo que asusta: el trueno es choque de nubes y descarga, no puntería divina; el mundo es átomos y vacío en movimiento, no un tribunal. La poesía es la miel del borde del vaso: hace pasar la explicación. Y visto el mecanismo, el miedo pierde a su cobrador: no desaparece del todo, pero baja al tamaño de lo que de verdad es. Ese gesto (curar enseñando cómo funciona) es el corazón de la misión."},{"q":"¿Qué es el tetrafármaco y cómo se aplica a un miedo de esta casa?","ans":"Es el remedio de cuatro frascos de la escuela de Epicuro: a los dioses no hay que temerles; la muerte no es nada para nosotros; el bien es fácil de conseguir; el dolor es corto o llevadero. Se aplica por escrito: se nombra el miedo (por ejemplo, la pregunta de Angelly después del funeral), se busca su mecanismo, se elige el frasco que le toca (el segundo: donde estamos nosotros no está la muerte), y se conversa como argumento, a la edad de quien pregunta y sin atropellar lo que la familia cree. El tetrafármaco es herramienta de mesa, no anestesia: el duelo es real y no se desmonta."},{"q":"¿En qué se equivoca exactamente quien confunde esta materia con el materialismo de tienda?","ans":"La entendió al revés. El materialismo de tienda necesita deseos sin límite: que el teléfono de este año pida el del que viene, que la felicidad se venda en cuotas. La escuela materialista más famosa de la historia enseñaba lo contrario: Epicuro vivía de pan y queso, clasificaba los deseos, y advertía que el deseo sin límite es el anzuelo, no el premio, porque nunca se llena. El materialismo filosófico pregunta de qué está hecho lo que te venden y quién lo sostiene: es la herramienta con que se le dice que no a la tienda, no su vitrina."},{"q":"¿Qué está superado y qué sigue vivo del atomismo de Demócrito?","ans":"Superada está la física: el átomo indivisible e indestructible, los átomos con ganchitos, los átomos finos del alma. El átomo de Demócrito no es el de la tabla periódica, y hasta el «átomo» moderno se parte. Vivo sigue el programa: lo que existe está hecho de algo, lo que pasa tiene mecanismo y no capricho, y lo que se presenta como venido de fuera del mundo se puede auditar. La ciencia entera terminó adoptando esa apuesta. Decir cuál es cuál, sin mezclarlas, es la cuarta regla de la etapa."},{"q":"¿Cómo llega Demócrito hasta nosotros, y por qué hay que decirlo al citarlo?","ans":"No nos llegó ninguno de sus libros entero: se le lee por fragmentos (citas sueltas en otros autores) y por doxografía (resúmenes antiguos que copian, ordenan y a veces deforman). Decirlo al citarlo es la regla del estatus aplicada a la Antigüedad: una frase de Demócrito llega con siglos de intermediarios, y quien la cita como si la hubiera leído en el original está inflando su fuente. Lo mismo vale para Epicuro: sus cartas sobreviven porque Diógenes Laercio las copió en su libro X, y Laercio es un compilador tardío, valioso y de segunda mano."},{"q":"¿Qué es el clinamen y qué problema intenta resolver?","ans":"Es la desviación mínima e impredecible que Lucrecio le atribuye al átomo en su caída. El problema que ataca es serio: si todo es materia cayendo en línea recta por leyes fijas, todo estaría ya decidido, y no habría lugar para la libertad ni sentido en dar consejos. El clinamen abre una holgura dentro de la materia para que la libertad quepa. Como física es un parche antiguo; como problema sigue abierto (la materia y la libertad se siguen discutiendo hoy), y verlo planteado en verso hace veintiún siglos enseña que el programa materialista carga sus propias preguntas difíciles, y las declara en vez de esconderlas."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> No hay más que átomos y vacío. → <span style="color:var(--jade);font-weight:700;">Atomismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

