function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"A Jael le llega por WhatsApp un curso de «abundancia y felicidad» a L 1.200: doce videos, un grupo de Telegram y la promesa de que la felicidad es una decisión diaria. Varias amigas ya pagaron."},{"txt":"Llega la cadena del eclipse: «el del viernes trae desgracias a quien no se prepare», con un kit de velas y sales a L 350 y la orden de reenviar a diez contactos. Angelly pregunta asustada si es cierto."},{"txt":"Jael pide un teléfono de L 18.000 «porque lo necesita para estudiar». El que tiene funciona; el nuevo es el que sale en los videos de sus amigas."},{"txt":"Un colegio ofrece L 8.000 por incluir en M.E.T.A.S una misión de «mentalidad de abundancia», con frases de motivación y visualización de riqueza."},{"txt":"Después del funeral de un vecino, Angelly no puede dormir y pregunta: «¿a dónde va uno cuando se muere?». No hay oferta ni lempiras: hay una niña despierta a las diez de la noche."},{"txt":"Un programa de radio ofrece una «oración de protección personalizada» por L 500 mensuales, con testimonios de desgracias que les cayeron a los que dejaron de pagar."},{"txt":"Un vendedor ofrece al autor un curso de «física cuántica de la prosperidad» a L 2.500, y propone que M.E.T.A.S lo revenda a sus usuarios."},{"txt":"Se anuncia un huracán. Al grupo de WhatsApp llegan dos mensajes: el aviso oficial con la ruta y las recomendaciones, y un video monetizado que grita que «esto es castigo» y pide donaciones."}];
const critCaseQuestions=["1. ¿Qué miedo o qué deseo sostiene este caso, y tiene límite o pide sin fin?","2. ¿Qué mecanismo hay detrás: quién lo enseña, quién lo esconde y quién cobra por mantenerlo escondido?","3. ¿Qué frasco del tetrafármaco, o qué distinción de la etapa, le toca a este caso?","4. ¿Qué condición escrita deja la casa, y qué se le contesta a quien trajo la oferta, sin burlarse de nadie?"];
const critCaseGuides=["Se busca primero el motor del caso: un miedo (el castigo, la muerte, la desgracia) o un deseo (la abundancia, el estatus, la pertenencia). Y se le mide el tope: el deseo natural y necesario se cumple y descansa; el deseo vano y el miedo difuso piden sin fin, y esa hambre perpetua es exactamente lo que la oferta necesita para renovarse. Un caso sin motor identificado no está auditado.","Después se pregunta por el mecanismo. Si alguien lo enseña (el aviso oficial, el video del eclipse, el experimento repetible), el caso se trabaja gratis. Si nadie lo enseña y en su lugar hay amenaza, testimonio o palabras de ciencia sin experimento, hay que buscar la caja: el miedo sin mecanismo casi siempre tiene un cobrador cerca, y nombrarlo es la mitad de la auditoría.","El tetrafármaco se aplica frasco por frasco: al castigo del cielo le toca el primero (a los dioses no se les teme, y el mecanismo del eclipse lo confirma); a la pregunta de la muerte, el segundo, conversado como argumento y no recetado; a la promesa de abundancia, la tabla de los deseos (el bien es fácil de conseguir: pan, techo, amigos); al dolor y al huracán, el cuarto y la preparación. Si ningún frasco calza, la distinción mecanismo contra amenaza suele resolver el resto.","Todo caso termina con la condición escrita, pensada en frío: qué tendría que mostrar la oferta para que el sí fuera posible (el mecanismo comprobable, el experimento repetible, el precio contra la alternativa gratuita), y qué se contesta sin burla, porque esta casa también vive dentro de creencias y también tiene miedos. Casi ninguna oferta se acepta o se rechaza completa: se acepta con condiciones, y las condiciones se escriben antes de contestar."];

const critErrorBank=[{"txt":"\"El materialismo es amar las compras y el lujo\".","g1":"Confunde la materia de estudio con la tienda: el materialismo filosófico pregunta de qué está hecho lo que te venden, y su escuela más famosa vivía de pan y queso.","g2":"La corrección exacta: esta escuela enseña que el deseo sin límite es el anzuelo, no el premio. Es la herramienta para decirle que no a la tienda, no su vitrina."},{"txt":"\"Si el átomo de Demócrito no es el de la química, todo el programa quedó refutado\".","g1":"Mezcla la física con el programa: la física antigua (átomo indivisible, ganchitos) sí está superada, y se dice sin pena.","g2":"El programa (todo está hecho de algo, todo tiene mecanismo) no solo sigue vivo: es la apuesta que la ciencia entera terminó adoptando. Se corrige separando las dos cosas."},{"txt":"\"Epicuro enseñaba a darse todos los gustos\".","g1":"Al revés: su escuela clasificaba los deseos y enseñaba que los naturales y necesarios se cumplen con poco, mientras el deseo vano nunca se llena.","g2":"El «placer» de Epicuro es la ausencia de dolor y de miedo, no el banquete: por eso el tetrafármaco es su centro y el pan con queso su mesa."},{"txt":"\"El eclipse trae castigo: mejor compro las velas, por si acaso\".","g1":"El «por si acaso» es el modelo de negocio: la amenaza no enseña mecanismo, y cobra exactamente porque no lo enseña.","g2":"La cura cuesta cero: el mecanismo del eclipse explicado. Visto el mecanismo, el castigo se queda sin oficio y las velas sin cliente."},{"txt":"\"A la niña no se le habla de la muerte, para que no se asuste\".","g1":"El miedo sin conversación no se apaga: crece de noche. Callarlo es dejárselo entero a quien sí quiera cobrárselo después.","g2":"El segundo frasco se conversa como argumento, a su edad y sin atropellar lo que la familia cree: el duelo es real y no se desmonta; el terror nocturno sí se trabaja."},{"txt":"\"El poema de Lucrecio es solo literatura bonita; la física sobra\".","g1":"Parte el poema por la mitad: la miel del borde existe para hacer pasar la medicina. Sin la física, el verso es vaso vacío.","g2":"La lectura completa es el gesto: física para curar, poesía para que la cura entre. Por eso se lee como clásico sólido y además como literatura, con las dos etiquetas."}];

const critDecisionBank=["El curso de abundancia de L 1.200 espera respuesta de Jael esta semana: ¿qué pregunta única se le hace a la oferta, y qué alternativa gratuita tiene la casa en la biblioteca?","La cadena del eclipse ya asustó a Angelly: ¿se le compran las velas, se le prohíbe el teléfono, o se hace otra cosa esta noche? ¿Qué exactamente?","Jael insiste con el teléfono de L 18.000: ¿cómo se parte la petición con la tabla de los deseos, y qué condición se le escribe?","El colegio ofrece L 8.000 por la misión de «mentalidad de abundancia» en M.E.T.A.S: ¿qué pregunta decide, y qué contrapropuesta honesta cabe?","Angelly pregunta por la muerte a las diez de la noche: ¿qué frasco se abre, cómo se conversa a su edad, y qué no se hace?","La «oración de protección» de L 500 mensuales suena en la radio de la casa: ¿qué se audita y qué se respeta, y cuál es la pregunta que termina la conversación?","El vendedor cuántico ofrece comisión por revender en M.E.T.A.S: ¿qué se le pide que muestre, y por qué la reventa ni se conversa?","El huracán viene en camino y llegaron los dos mensajes: ¿cuál se convierte en lista, cuál se archiva como espécimen, y qué aprende la familia del par?"];
const critDecisionGuide="La decisión correcta sigue siempre el mismo orden. Primero se nombra el motor del caso: qué miedo o qué deseo lo sostiene, y se le mide el tope, porque el deseo con límite se cumple y descansa mientras el vano y el miedo difuso piden sin fin. Después se pregunta por el mecanismo: si alguien lo enseña, el caso se trabaja gratis; si nadie lo enseña y en su lugar hay amenaza, testimonio o palabras de ciencia sin experimento, se busca la caja y se nombra al cobrador. Luego se abre el botiquín: el frasco del tetrafármaco que calce, o la distinción de la etapa que resuelva, conversado y no recetado, porque esta casa desmonta miedos sin burlarse de quien los vive. Y al final se escribe la condición, pensada en frío: qué tendría que mostrar la oferta para el sí, y qué se contesta sin pelear, porque casi nada se acepta ni se rechaza completo, se acepta con condiciones escritas antes de contestar.";

const critCompareBank=[{"a":"Explicar el mecanismo del eclipse con un video, juntos.","b":"Comprar el kit de velas de L 350, por si acaso.","ga":"Caso A: el miedo se desarma de raíz y gratis, y Angelly aprende un gesto que sirve para todas las cadenas que vienen.","gb":"Caso B: se paga la cuota del miedo, la cadena queda confirmada como verdadera, y el próximo kit ya tiene cliente.","gr":"La diferencia no es el gasto: es quién se queda con el miedo. El mecanismo lo apaga; la compra lo alquila y lo renueva."},{"a":"Leer la Carta a Meneceo, que es gratis y cabe en una tarde.","b":"Pagar L 1.200 por el curso de abundancia de doce videos.","ga":"Caso A: la versión seria del mismo tema, de primera mano, con veintitrés siglos de servicio comprobado y sin grupo de Telegram.","gb":"Caso B: la promesa de un deseo sin límite, que no se llena y por diseño pide el siguiente curso.","gr":"Cuando la alternativa gratuita es mejor que la de pago, la oferta no compite con la biblioteca: compite con no haberla abierto."},{"a":"Cubrir el teléfono de L 4.000 que cumple el deseo con límite.","b":"Pagar los L 18.000 del teléfono que sale en los videos.","ga":"Caso A: el deseo natural (estudiar con un aparato que funcione) se cumple y descansa, y quedan L 14.000 para lo que sí tiene fondo.","gb":"Caso B: se compra estatus, que es deseo sin límite: el año que viene el aparato nuevo será viejo y la petición volverá más cara.","gr":"La tabla de los deseos no es tacañería: es saber qué parte del precio compra la cosa y qué parte alimenta el anzuelo."},{"a":"El aviso oficial del huracán, convertido en lista de preparación.","b":"El video del castigo, con su enlace de donación.","ga":"Caso A: miedo con mecanismo: enseña de qué está hecho el peligro y qué hacer, y termina en agua, radio y documentos en alto.","gb":"Caso B: miedo con cobrador: no prepara nada, sube el pánico y lo monetiza; es el tetrafármaco al revés.","gr":"El mismo huracán produce los dos miedos: el que se trabaja cuesta cero lempiras, y el que se compra no protege de nada."}];

const critCauseBank=[{"cause":"La cadena amenaza sin explicar el mecanismo del eclipse.","guide":"El miedo queda entero y sin dueño, el kit de velas encuentra cliente, y la próxima cadena llega a una casa que ya demostró que paga."},{"cause":"La casa explica el mecanismo de lo que asusta, juntos y sin burla.","guide":"El miedo baja al tamaño de lo que de verdad es, el cobrador se queda sin oficio, y las niñas aprenden el gesto de Lucrecio para la siguiente amenaza."},{"cause":"Se alimenta un deseo sin límite como si fuera necesidad.","guide":"El deseo se cumple y no descansa: pide el siguiente teléfono, el siguiente curso, la siguiente cuota, y el presupuesto de la casa financia un pozo sin fondo."},{"cause":"Se cita a Demócrito como si sus libros se conservaran enteros.","guide":"La fuente queda inflada: lo que llega es fragmento y doxografía con siglos de intermediarios, y quien no lo declara le presta a su cita una firmeza que no tiene."},{"cause":"La pregunta de la muerte se calla «para no asustar».","guide":"El miedo crece de noche y sin conversación, y queda disponible entero para el primer cobrador que pase con una promesa y una tarifa."},{"cause":"Una oferta usa palabras de ciencia sin experimento que mostrar.","guide":"La física funciona como decorado: presta autoridad sin prestar mecanismo, y el único flujo comprobable termina siendo el precio del curso."}];
const critEffectBank=[{"effect":"La cadena del eclipse murió en el teléfono de la casa, sin reenvío ni compra.","guide":"Se abrió el video del mecanismo y lo miraron juntos: visto cómo funciona, la amenaza quedó sin oficio, y Angelly aprendió la pregunta que mata cadenas: ¿quién gana si el miedo sigue vivo?"},{"effect":"Jael declinó el curso de abundancia sin pelear con sus amigas.","guide":"Se hizo la pregunta única: ¿qué sabe hacer quien lo termina que no supiera antes? El silencio bastó, y la Carta a Meneceo (gratuita y de una tarde) quedó como la versión seria del tema."},{"effect":"El teléfono se resolvió con L 4.000 y sin drama.","guide":"La tabla de los deseos partió la petición: el deseo con límite (estudiar) lo cubrió la casa; el deseo de estatus, si lo quiere, lo ahorra ella, y con eso se mide solo."},{"effect":"La conversación de la muerte terminó con Angelly dormida y sin sustos nuevos.","guide":"Se abrió el segundo frasco como argumento y a su edad: donde estamos nosotros no está la muerte. La familia terminó la conversación con lo suyo, y el miedo dejó de crecer a oscuras."},{"effect":"La casa pasó el huracán preparada y sin donar al pánico.","guide":"El aviso oficial se volvió lista (agua, radio, documentos en alto) y el video del castigo se archivó como espécimen de miedo con cobrador para esta misión."},{"effect":"El vendedor cuántico no volvió a llamar.","guide":"Se le pidió lo único que la física de verdad siempre tiene: el experimento que cualquiera puede repetir. No existía, y la reventa en M.E.T.A.S ni se conversó: la plataforma enseña lo contrario."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 El miedo sobre la mesa · Forma ${cf} · Átomos contra el miedo · Ruta de los Átomos y los Ídolos`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. El miedo sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué miedo o deseo sostiene el caso y con qué tope, qué mecanismo hay detrás y quién cobra por esconderlo, y qué frasco o distinción de la etapa lo resuelve? Explica la condición escrita que deja la casa y qué se contesta sin burlarse de nadie.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos enseña el mecanismo antes de pedir algo? 2. ¿Por qué no son la misma decisión?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El miedo sobre la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. El miedo sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué miedo o deseo sostiene el caso y con qué tope, qué mecanismo hay detrás y quién cobra por esconderlo, y qué frasco o distinción de la etapa lo resuelve? Explica la condición escrita que deja la casa y qué se contesta sin burlarse de nadie.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos enseña el mecanismo antes de pedir algo? 2. ¿Por qué no son la misma decisión?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El miedo sobre la mesa Átomos contra el miedo · Ruta de los Átomos y los Ídolos · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #92400e;background:#f6ede2;color:#92400e;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#92400e;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #92400e;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#f6ede2;border-left:3px solid #92400e;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#f6ede2;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#f6ede2;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#92400e;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #92400e;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El miedo sobre la mesa · Átomos contra el miedo · Ruta de los Átomos y los Ídolos · Etapa 1 · Estudio Mayor</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El miedo sobre la mesa · Átomos contra el miedo · Ruta de los Átomos y los Ídolos · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

