const timelineData=[{"y":"S. V a. C.","icon":"🏺","label":"Átomos y vacío","text":"<strong>Leucipo y Demócrito</strong> proponen que no hay más que átomos y vacío. <strong>Aporta:</strong> el programa entero en una frase. <strong>Cuidado:</strong> no queda libro entero; se les lee por fragmentos y doxografía, y así se dice."},{"y":"306 a. C.","icon":"🏛️","label":"El Jardín","text":"Epicuro funda su escuela en Atenas: <strong>el Jardín</strong>, con amigos, pan y queso. <strong>Aporta:</strong> la física convertida en medicina. <strong>Cuidado:</strong> desde entonces lo caricaturizan como glotón; era casi lo contrario."},{"y":"~300 a. C.","icon":"✉️","label":"La Carta a Meneceo","text":"La medicina resumida en una carta que <strong>cabe entera en una tarde</strong>: los dos miedos, el tetrafármaco, la tabla de los deseos. <strong>Sobrevive</strong> porque Diógenes Laercio la copia siglos después en su libro X."},{"y":"S. I a. C.","icon":"📜","label":"De rerum natura","text":"Lucrecio pone el programa <strong>en seis libros de verso</strong>: la miel del borde, el clinamen, el miedo desarmado con mecanismo. <strong>Aporta:</strong> el gesto que es el corazón de esta misión. Clásico sólido y además literatura."},{"y":"1417","icon":"🔦","label":"El manuscrito","text":"Poggio Bracciolini encuentra en un monasterio una copia de De rerum natura <strong>que estuvo a nada de perderse</strong>. Greenblatt lo cuenta en El giro: <strong>divulgación con inflado</strong>: buen relato, Edad Media en caricatura."},{"y":"S. XIX y XX","icon":"⚗️","label":"La física se va","text":"La química y la física modernas toman la palabra «átomo» y la cambian entera: <strong>el de Demócrito no es el de la tabla periódica</strong>, y el moderno hasta se parte. <strong>La física antigua queda superada, y se dice sin pena.</strong>"},{"y":"Hoy","icon":"⚛️","label":"El programa vivo","text":"Lo que sigue en pie: <strong>todo lo que actúa está hecho de algo</strong>, lo que pasa tiene mecanismo, y lo que se presenta venido de fuera se audita. <strong>En esta casa:</strong> la pregunta operativa se corre contra miedos y ofertas reales."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(mecanismo){sfx(mecanismo?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(mecanismo){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🔬</span><span class="ms-text"><strong>Abrieron juntos el video del mecanismo:</strong> la Luna pasa por la sombra de la Tierra, con fecha calculada desde hace años. Angelly lo vio entero y preguntó dos veces «¿solo eso?».</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">⚛️</span><span class="ms-text"><strong>El miedo perdió a su cobrador:</strong> la cadena murió sin reenvío, las velas se quedaron sin cliente, y quedó aprendida la pregunta que mata cadenas: ¿quién gana si el miedo sigue vivo?</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🕯️</span><span class="ms-text"><strong>Se compraron las velas «por si acaso»:</strong> L 350 al cobrador, y algo peor que el gasto: la cadena quedó confirmada como verdadera delante de Angelly.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🌩️</span><span class="ms-text"><strong>El miedo se quedó a vivir:</strong> nadie enseñó el mecanismo, así que la próxima cadena llega a una casa que ya demostró que paga. El «por si acaso» es exactamente el modelo de negocio.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

