const lectComprensionBank=[{"t":"Borges","q":"¿Qué vendía Molinari durante el paso del cometa Halley, en mayo de 1910?","o":["a) Mapas del cielo con la órbita del cometa","b) Velas, sales y cinta roja","c) Píldoras contra el cometa, una por noche","d) Ejemplares del poema de Lucrecio"],"c":2},{"t":"Borges","q":"¿Qué «despachaba» el abuelo boticario a los vecinos asustados, sin cobrarlo?","o":["a) Una explicación: el mapa del cielo, la órbita, y que la cola es materia tan tenue como el humo","b) Valeriana al doble de precio","c) Cédulas para dormir con ellas bajo la almohada","d) Un amuleto bendecido por si acaso"],"c":0},{"t":"Borges","q":"¿Qué libro guardaba el abuelo detrás del mostrador?","o":["a) Un tratado moderno de astronomía","b) Las vidas de Diógenes Laercio completas","c) Un recetario de botica en latín","d) Una edición escolar del De rerum natura de Lucrecio"],"c":3},{"t":"Borges","q":"¿De qué estaban hechas las píldoras de Molinari, según el análisis que hizo años después un condiscípulo del narrador?","o":["a) De valeriana","b) De azúcar","c) De harina y miel","d) Nunca se pudo saber"],"c":1},{"t":"Borges","q":"¿Cómo remata el abuelo la comparación entre las píldoras y el miedo?","o":["a) Diciendo que Molinari era un estafador y él un sabio","b) Diciendo que el azúcar también está hecha de átomos, y el miedo que Molinari vendía, de vacío","c) Diciendo que el cometa volvería y le daría la razón","d) Diciendo que la valentía no se puede comprar"],"c":1},{"t":"Cervantes","q":"¿Qué vendía el buhonero en la venta, la noche del cometa?","o":["a) Cédulas escritas para dormir con una bajo la almohada, «casi de balde»","b) Estampas del cometa a dos cuartos","c) Un elixir contra el granizo","d) Reliquias traídas de Salamanca"],"c":0},{"t":"Cervantes","q":"¿Qué única pregunta propuso el estudiante hacerle al buhonero antes de pagar?","o":["a) Cuánto costaba la cédula sin el casi","b) Quién le había enseñado el oficio","c) Si él mismo dormía con una cédula","d) De qué está hecho el cometa, y qué lo sostiene"],"c":3},{"t":"Cervantes","q":"Cuando el buhonero se atribuyó a la mañana que no hubiera pasado desgracia alguna, ¿qué le respondió Sabina?","o":["a) Que le devolviera el dinero de la cédula","b) Que el cometa aún podía volver","c) Que también su gallo canta cada día antes de salir el sol, y no por eso lo saca él","d) Que las cédulas eran de papel de estraza"],"c":2},{"t":"Cervantes","q":"Según contó el estudiante, ¿cuál era el secreto del mono adivino de aquel titiritero?","o":["a) Que el mono entendía el habla de los hombres","b) Que su amo se informaba antes en los mesones: el arte estaba en esconder el mecanismo","c) Que solo adivinaba las cosas por venir","d) Que el titiritero le soplaba las respuestas con silbidos"],"c":1},{"t":"Cervantes","q":"¿Qué regla quedó escrita con carbón sobre la puerta de la venta?","o":["a) Al miedo que explique su mecanismo, cama y mesa; al miedo que venga con cobrador, ni cuadra","b) Que no entrara buhonero sin pagar por adelantado","c) Que en la venta no se hablara más de cometas","d) Que toda cédula se mirara contra la luz del candil"],"c":0},{"t":"Harari","q":"Según el ensayo, ¿qué nos distingue como especie frente al miedo?","o":["a) Que somos la especie que menos miedos tiene","b) Que aprendemos de los miedos ajenos","c) Que olvidamos los miedos con más rapidez que los otros animales","d) Que somos la única especie que paga por miedos que nadie le puede mostrar"],"c":3},{"t":"Harari","q":"¿Cuál es la estructura del «modelo de negocio más antiguo del mundo»?","o":["a) Un producto caro, un vendedor insistente y una rebaja final","b) Una amenaza invisible, un intermediario que dice saber aplacarla y una tarifa renovable","c) Una promesa de riqueza, un curso y un grupo de Telegram","d) Un monopolio, un arancel y un contrabandista"],"c":1},{"t":"Harari","q":"¿Qué observación de Epicuro describe, según el ensayo, el modelo de negocio de media internet?","o":["a) Que el deseo sin límite no se llena nunca: es el anzuelo, no el premio","b) Que el dolor fuerte es corto","c) Que el bien es fácil de conseguir","d) Que a los dioses no hay que temerles"],"c":0},{"t":"Harari","q":"¿Qué honestidad pide el ensayo sobre el atomismo antiguo?","o":["a) Reconocer que Demócrito nunca existió","b) Admitir que la física moderna le dio la razón en todo","c) Decir que como física está superado, pero que el programa de buscar mecanismo sigue vivo y ganando","d) Ocultar sus errores para no confundir al lector"],"c":2},{"t":"Harari","q":"¿Cuál es, para el ensayo, la única novedad real de nuestro siglo en el mercado del miedo?","o":["a) Que el miedo ya no se puede vender","b) Que las amenazas son ahora verdaderas","c) Que los intermediarios desaparecieron","d) Que el miedo y su antídoto viajan por el mismo canal, al mismo precio y a la misma velocidad"],"c":3},{"t":"Entrevista","q":"¿Qué contesta Lucrecio cuando Soler Serrano le confiesa que su carpeta biográfica está en blanco?","o":["a) Que su vida está contada en el libro sexto del poema","b) Que es un alivio: de él no se sabe casi nada, es una voz sin expediente, y todo lo que fue cabe en seis libros","c) Que San Jerónimo escribió su biografía completa","d) Que Cicerón guardó sus cartas personales"],"c":1},{"t":"Entrevista","q":"¿Qué dice Lucrecio de la historia del filtro de amor?","o":["a) Que es verdadera y prefiere no hablar de ella","b) Que la inventó Diógenes Laercio en el libro X","c) Que la nota de San Jerónimo existe, pero llega cuatro siglos tarde, de un autor que no simpatizaba con su escuela, y los historiadores desconfían","d) Que se refiere a otro poeta del mismo nombre"],"c":2},{"t":"Entrevista","q":"¿Por qué escribió la física en verso, según su propia imagen?","o":["a) Porque el verso es la miel en el borde del vaso, que hace pasar la medicina amarga","b) Porque los tratados estaban prohibidos en Roma","c) Porque Memio se lo exigió como pago","d) Porque no dominaba la prosa"],"c":0},{"t":"Entrevista","q":"A propósito de Ifigenia, ¿contra qué dice Lucrecio que apunta su poema?","o":["a) Contra toda creencia, sin distinción","b) Contra los poetas que escriben de dioses","c) Contra los sacerdotes de su siglo, con nombre y apellido","d) Contra el miedo con cobrador: la amenaza sin explicación, el intermediario y la factura que siempre paga otro"],"c":3},{"t":"Entrevista","q":"¿Qué le recomienda Lucrecio a la niña que no puede dormir por el eclipse?","o":["a) Que rece hasta que pase el viernes","b) Que no le compre nada al miedo y pida que le enseñen el mecanismo, con una naranja y una lámpara","c) Que lea los seis libros del poema esa misma noche","d) Que apague el teléfono para siempre"],"c":1},{"t":"Quintero y Gala","q":"¿Qué distinción hace Gala cuando Quintero le pregunta si le teme a la muerte?","o":["a) Que el miedo es de jóvenes y él ya es viejo","b) Que la muerte no existe para los poetas","c) Que le tiene consideración, no miedo: saber que la vecina vendrá y tenerle la casa recogida","d) Que prefiere no pensar en ella hasta que llegue"],"c":2},{"t":"Quintero y Gala","q":"Según Gala, ¿por qué el que quiere asustar enseña el cielo o la tumba?","o":["a) Porque son los dos únicos escenarios donde el público no puede subir a comprobar el decorado","b) Porque son los lugares más hermosos","c) Porque la gente ya no teme a los lobos","d) Porque así lo mandan los libretos antiguos"],"c":0},{"t":"Quintero y Gala","q":"¿En qué imagen de teatro convierte Gala la frase de Epicuro sobre la muerte?","o":["a) En un telón que nunca sube","b) En un apuntador que se queda dormido","c) En un estreno suspendido por lluvia","d) En dos actores que jamás comparten función, con taquilla vendida para un encuentro que no se celebra"],"c":3},{"t":"Quintero y Gala","q":"¿Cómo distingue Gala el cielo que consuela del cielo que factura?","o":["a) Por la antigüedad de cada uno","b) Al que factura se le piden los papeles, como a todo el que cobra; y recuerda que Troylo jamás le cobró por quererlo","c) Por el idioma en que se predica","d) Consultando a Séneca, que era cordobés"],"c":1},{"t":"Quintero y Gala","q":"¿Cuál es el aforismo con que Gala cierra la conversación?","o":["a) La muerte es una vecina de Córdoba","b) La física es la poesía de los cobardes","c) El miedo es el único acreedor que cobra sin haber prestado nada; con no abrirle la cuenta, está pagado","d) Quien mucho abarca poco aprieta"],"c":2}];
const lectCompletarBank=[{"t":"las cinco","q":"Epicuro vivió del año 341 al ___ antes de Cristo.","a":"270"},{"t":"las cinco","q":"De rerum natura, el poema de Lucrecio, tiene ___ libros.","a":"seis"},{"t":"las cinco","q":"El manuscrito de Lucrecio se recuperó en un monasterio en el año ___.","a":"1417"},{"t":"las cinco","q":"Leucipo y Demócrito propusieron que no hay más que átomos y ___.","a":"vacío"},{"t":"las cinco","q":"El remedio de cuatro frases de Epicuro se llama ___.","a":"tetrafármaco"},{"t":"las cinco","q":"La carta de Epicuro que cabe entera en una tarde es la Carta a ___.","a":"Meneceo"},{"t":"Entrevista","q":"La desviación mínima e impredecible del átomo, que intenta salvar la libertad, se llama ___.","a":"clinamen"},{"t":"las cinco","q":"El médico del poema unta ___ en el borde del vaso para que el niño se tome la medicina amarga.","a":"miel"},{"t":"Harari","q":"Las cartas de Epicuro se preservaron en el libro ___ de las «Vidas» de Diógenes Laercio.","a":"X"},{"t":"Borges","q":"A Demócrito, que no nos llegó entero, se le lee por fragmentos y por ___.","a":"doxografía"}];
const lectAnalisisBank=[{"q":"1. Las cinco lecturas llegan al mismo remedio por cinco puertas. Explica qué hace cada voz que las otras no pueden hacer, y qué se perdería leyendo solo una.","guia":"El cuento vuelve el remedio una herencia con objetos: la botica llena en la semana del cometa, las píldoras que resultaron ser de azúcar y el libro que no se agotaba nunca; esa materialidad fija la idea mejor que cualquier definición. El capítulo la vuelve escena y risa: el buhonero pregonando, la pregunta del estudiante y el gallo de Sabina desarman el negocio con humor, que es la memoria más duradera. El ensayo pone la escala de especie y encadena la erudición con fechas comprobables: siglo V, 341 a 270, siglo I, 1417. La entrevista hace lo que el relato no puede: sienta al personaje real con su biografía en blanco delante y lo obliga a responder por la leyenda de San Jerónimo, es decir, aplica el método al propio testigo. Y la conversación baja el concepto al habla viva de dos andaluces reales, de noche, donde el tetrafármaco se vuelve confidencia y aforismo. Leyendo solo una se tendría imagen sin datos, o datos sin imagen, o doctrina sin voz; las cinco juntas dan el mecanismo, la prueba y la manera de contarlo."},{"q":"2. El cuento cierra con la frase del abuelo: el azúcar también está hecha de átomos; el miedo que Molinari vendía estaba hecho de vacío. Explica esa frase con las piezas de la etapa.","guia":"La frase juega con la fórmula fundadora de Leucipo y Demócrito: no hay más que átomos y vacío. Las píldoras, aunque fraudulentas, eran al menos una cosa: azúcar, materia, átomos; se les podía hacer la pregunta operativa de la etapa (¿de qué está hecho?) y contestarla con un análisis de laboratorio. El miedo que sostenía el negocio, en cambio, no resistía esa pregunta: no tenía mecanismo, ni explicación, ni sustancia; solo amenaza y caja registradora. Era, en el sentido más literal del programa, vacío. La elegancia está en que el boticario no niega el miedo ni insulta a quien compró: lo audita con la vara de la materia y muestra que del lado del cobrador no había nada. Es la misma auditoría que la casa aplica a la cadena del eclipse y al curso cuántico: donde no se puede decir de qué está hecho ni qué lo sostiene, lo que queda es el cobro."},{"q":"3. En el capítulo, el buhonero se atribuye a la mañana que no hubo desgracias, y Sabina contesta con su gallo. Explica qué error de razonamiento desarma ese refrán y por qué ese error es el sostén del negocio del miedo.","guia":"El buhonero comete el error de tomar la secuencia por causa: como vendió cédulas y no pasó nada, concluye que las cédulas obraron. Sabina lo desarma con un ejemplo perfecto de la misma forma: el gallo canta antes de salir el sol todos los días, y nadie sensato concluye que el canto saca el sol. El error es el sostén del negocio porque el miedo sin mecanismo siempre gana la apuesta: si no pasa nada, el remedio funcionó; si pasa algo, faltó pagar más o pagar a tiempo. Es un negocio sin manera de perder, exactamente como la suscripción de la radio del caso 6, donde dejar de pagar es el único pecado del catálogo. El único ataque que lo derrota no es discutir el resultado, sino exigir el mecanismo por adelantado: la pregunta del estudiante (de qué está hecho y qué lo sostiene) hecha antes de abrir la bolsa."},{"q":"4. El mono adivino de maese Pedro solo respondía de lo pasado y lo presente, y su secreto era que el amo se informaba antes. Explica por qué el estudiante lo usa como espejo de las cédulas y qué enseña ese ejemplo sobre esconder el mecanismo.","guia":"El mono parecía magia mientras su mecanismo estuvo escondido: el titiritero recogía en cada pueblo los datos de la gente, y el prodigio era información disfrazada. Por eso solo «adivinaba» lo pasado y lo presente: de lo por venir no hay mesón donde informarse. El estudiante lo usa como espejo porque las cédulas funcionan con la misma arquitectura invertida: el buhonero tampoco enseña su mecanismo, pero no porque esconda uno ingenioso, sino porque no hay ninguno. El ejemplo enseña la regla general de la etapa: el poder de un prodigio está en la parte que no se deja ver, y quien pregunta por el mecanismo desactiva el prodigio en los dos casos, el del truco con secreto (el mono) y el del secreto sin truco (las cédulas). Lucrecio hizo lo contrario exacto: enseñó el mecanismo para curar, en vez de esconderlo para cobrar."},{"q":"5. El ensayo dice que el miedo es el relato más barato de producir y el más caro de mantener. Explica las dos mitades de la frase y conéctalas con el caso de la cuota de protección de L 500 mensuales.","guia":"Es barato de producir porque una amenaza no necesita pruebas: basta con que no se pueda descartar, y anunciar desgracias no cuesta nada; la cadena del eclipse se redacta en un minuto. Es caro de mantener porque el miedo sin explicación no se acaba nunca: no hay un momento en que quede satisfecho, así que quien lo padece puede pagar indefinidamente. De esa asimetría sale la tarifa renovable: el negocio no vende un producto, vende la renovación de un alivio que caduca solo. El caso de la radio es la fórmula pura: la «oración de protección personalizada» cuesta L 500 al mes precisamente porque el miedo se renueva solo, los testimonios de desgracias reponen el susto cada semana, y dejar de pagar es el único pecado del catálogo. El tetrafármaco ataca la mitad cara: visto el mecanismo, el miedo deja de renovarse, y con él la cuota."},{"q":"6. La entrevista dedica sus dos primeras preguntas a la biografía vacía de Lucrecio y a la leyenda de San Jerónimo. Explica por qué ese par de preguntas enseña el método de la etapa aplicado al propio poeta.","guia":"Porque somete al testigo a su propia vara. De Lucrecio no se sabe casi nada cierto, y la única «biografía» que circula es una nota escrita cuatro siglos después por San Jerónimo, un autor hostil a su escuela: el filtro de amor, la locura, el suicidio. La entrevista no la esconde ni la repite como hecho: la pone sobre la mesa, declara su fuente, su distancia y su sesgo, y deja que el propio Lucrecio señale la ironía de que su vida sea un rumor sin pruebas. Eso es exactamente el método de la etapa: preguntar de qué está hecha una afirmación y qué la sostiene, incluso cuando la afirmación es sabrosa y le daría color al programa. Una entrevista que usara la leyenda como dato, o que inventara una infancia para llenar la carpeta, sería erudición inflada: la misma píldora de azúcar que el cuento denuncia."},{"q":"7. Lucrecio dice que no escribió contra la fe de nadie sino contra el miedo con cobrador. Explica la diferencia usando las dos columnas de la etapa y la regla de la casa.","guia":"Las dos columnas de la etapa separan el miedo con mecanismo (el huracán anunciado, que se convierte en lista y preparación) del miedo con cobrador (la amenaza que no explica nada y tiene una caja registradora cerca). La escena de Ifigenia muestra el segundo en su forma extrema: amenaza sin explicación, intermediario que administra el terror y factura que paga otro. Lucrecio declara su pleito con esa estructura, no con el consuelo ni con la creencia de la gente: donde hay explicación y consuelo, dice, no tiene pleito. Esa es también la regla doble de la casa en el caso de la radio: la fe de la familia se respeta, y el cobro por miedo se desmonta venga con la palabra que venga. La diferencia práctica está en la pregunta que se hace: no «¿qué crees?», que no es asunto de nadie, sino «¿qué pasa exactamente si dejas de pagar, y quién lo documenta?»."},{"q":"8. El clinamen aparece en la entrevista y en la conversación. Explica qué problema intenta resolver dentro del atomismo y qué hace Gala con él cuando dice que los que venden miedo odian la física.","guia":"El problema es el determinismo: si solo hay átomos cayendo en línea recta por el vacío, todo choque y toda historia estarían decididos desde siempre, y no habría lugar para la libertad. Lucrecio propuso la desviación mínima e impredecible del átomo, el clinamen, como la rendija por donde la libertad entra en la materia: hasta la libertad quiso sacarla del mecanismo y no del milagro. Gala lo convierte en imagen de su propio oficio: sus personajes de teatro son desviaciones que no estaban en el guion, y de ahí saca la vuelta polémica: los que venden miedo necesitan obediencia total, un mundo donde todo esté ya decidido y solo quede pagar o temblar; una física donde ni los átomos obedecen del todo les arruina el modelo, porque enseña que el desvío es posible y que no estaba en el libreto del cobrador. La pauta no exige decidir si el clinamen es buena física: exige entender qué apuesta hace."},{"q":"9. Explica el aforismo final de Gala (el miedo es el único acreedor que cobra sin haber prestado nada) conectándolo con el tetrafármaco y con al menos dos casos de la misión.","guia":"Un acreedor legítimo cobra porque antes entregó algo: dinero, mercancía, trabajo. El miedo sin mecanismo cobra sin haber entregado nada: ni explicación, ni protección comprobable, ni bien alguno; su única mercancía es la amenaza que él mismo fabrica. El tetrafármaco es la manera de no abrirle la cuenta: sin miedo a los dioses ni a la muerte, las dos hipotecas mayores quedan canceladas antes de firmarse, y el bien fácil de conseguir (pan, agua, techo, amigos) deja al cobrador sin más puertas. En los casos de la misión el acreedor aparece con caja a la vista: el kit del eclipse cobra L 350 por una sombra que no debe nada, la cuota de la radio cobra L 500 mensuales por desgracias que solo existen en los testimonios, y el curso cuántico cobra L 2.500 por una vibración que nunca se mide. En los tres, la casa no paga con burla sino con auditoría: pide el mecanismo, y al no aparecer, cierra la cuenta."},{"q":"10. Las cinco lecturas llevan etiqueta de ejercicio de estilo, y las dos entrevistas declaran además que el encuentro nunca ocurrió. Explica por qué esa honradez es parte del temario de esta etapa, y qué pasaría si se quitara.","guia":"La etapa enseña a desconfiar de lo que asusta o promete sin enseñar su mecanismo, y una lectura que fingiera ser de Borges, o una entrevista que se hiciera pasar por real, sería exactamente esa mercancía: prestigio sin sustancia, la píldora de azúcar con etiqueta de remedio. Declarar el pastiche y el encuentro imaginado es enseñar el mecanismo del propio texto: se muestra quién lo escribió, qué se imita, qué es invención (la conversación) y qué es comprobable (todas las obras, fechas y cifras de adentro). Si se quitara la etiqueta pasarían dos cosas. La primera, práctica: una hoja impresa viaja sola, se fotocopia, y alguien acabaría citando una entrevista de Soler Serrano a Lucrecio que jamás existió, con lo que la casa habría fabricado el rumor sin pruebas que su propia sonda caza. La segunda, peor: la lección quedaría desmentida por el ejemplo, y quien descubriera el truco tendría razón en desconfiar de todo lo demás, incluidos los datos verdaderos."}];
const xpLect={c:new Set(),f:new Set()};

/* ---------- I. Comprensión lectora ---------- */
let lcIdx=0,lcSel=-1,lcDone=false;
function showLectC(){const cont=document.getElementById('lcQ');if(!cont)return;if(lcIdx>=lectComprensionBank.length){cont.textContent='🎉 ¡Comprensión lectora completada!';document.getElementById('lcOpts').innerHTML='';document.getElementById('lcProg').textContent='Las '+lectComprensionBank.length+' preguntas respondidas';unlockAchievement('lect_master');return;}const q=lectComprensionBank[lcIdx];document.getElementById('lcProg').textContent='Pregunta '+(lcIdx+1)+' de '+lectComprensionBank.length+' · '+q.t;cont.textContent=q.q;const opts=document.getElementById('lcOpts');opts.innerHTML='';lcSel=-1;lcDone=false;q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=o;b.onclick=()=>{if(lcDone)return;opts.querySelectorAll('.qz-opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');lcSel=i;sfx('click');};opts.appendChild(b);});}
function checkLectC(){if(lcIdx>=lectComprensionBank.length)return;if(lcSel<0)return fb('fbLC','Selecciona una respuesta.',false);lcDone=true;const opts=document.querySelectorAll('#lcOpts .qz-opt');if(lcSel===lectComprensionBank[lcIdx].c){opts[lcSel].classList.add('correct');fb('fbLC','¡Correcto! +2 XP',true);if(!xpLect.c.has(lcIdx)){xpLect.c.add(lcIdx);pts(2);}sfx('ok');}else{opts[lcSel].classList.add('wrong');opts[lectComprensionBank[lcIdx].c].classList.add('correct');fb('fbLC','Incorrecto. Vuelve al texto: la respuesta está ahí.',false);sfx('no');}setTimeout(()=>{lcIdx++;showLectC();},1700);}
function resetLectC(){sfx('click');lcIdx=0;showLectC();document.getElementById('fbLC').classList.remove('show');}

/* ---------- II. Completar ---------- */
let lfIdx=0;
function showLectF(){const cont=document.getElementById('lfQ');if(!cont)return;if(lfIdx>=lectCompletarBank.length){cont.innerHTML='🎉 ¡Las diez oraciones completadas!';document.getElementById('lfProg').textContent='Terminado';const inp=document.getElementById('lfInput');if(inp)inp.style.display='none';return;}const d=lectCompletarBank[lfIdx];document.getElementById('lfProg').textContent='Oración '+(lfIdx+1)+' de '+lectCompletarBank.length+' · '+d.t;cont.innerHTML=d.q.replace('___','<span class="blank">___</span>');const inp=document.getElementById('lfInput');if(inp){inp.style.display='';inp.value='';inp.classList.remove('eval-input-ok','eval-input-no');}}
function checkLectF(){if(lfIdx>=lectCompletarBank.length)return;const inp=document.getElementById('lfInput');const d=lectCompletarBank[lfIdx];if(!inp.value.trim())return fb('fbLF','Escribe tu respuesta.',false);const ok=isCpCorrect(inp.value,d.a);inp.classList.toggle('eval-input-ok',ok);inp.classList.toggle('eval-input-no',!ok);if(ok){fb('fbLF','¡Correcto! +2 XP',true);if(!xpLect.f.has(lfIdx)){xpLect.f.add(lfIdx);pts(2);}sfx('ok');}else{fb('fbLF','Todavía no. La respuesta esperada era: '+d.a,false);sfx('no');}setTimeout(()=>{lfIdx++;showLectF();document.getElementById('fbLF').classList.remove('show');},1900);}
function resetLectF(){sfx('click');lfIdx=0;showLectF();document.getElementById('fbLF').classList.remove('show');}

/* ---------- III. Análisis complejo ---------- */
let laIdx=0,laPautaVisible=false;
function showLectA(){const cont=document.getElementById('laQ');if(!cont)return;const d=lectAnalisisBank[laIdx];document.getElementById('laProg').textContent='Pregunta '+(laIdx+1)+' de '+lectAnalisisBank.length;cont.textContent=d.q;const p=document.getElementById('laPauta');p.innerHTML='<strong>Pauta:</strong> '+d.guia;p.style.display=laPautaVisible?'block':'none';document.getElementById('laTA').value='';}
function nextLectA(){sfx('click');laIdx=(laIdx+1)%lectAnalisisBank.length;showLectA();}
function prevLectA(){sfx('click');laIdx=(laIdx-1+lectAnalisisBank.length)%lectAnalisisBank.length;showLectA();}
function toggleLectAPauta(){sfx('click');laPautaVisible=!laPautaVisible;const p=document.getElementById('laPauta');p.style.display=laPautaVisible?'block':'none';const b=document.getElementById('btnLectAPauta');if(b)b.textContent=laPautaVisible?'🙈 Ocultar pauta':'👁 Ver pauta';}

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso: una hoja
// suelta con un pastiche sin declarar sería la píldora de azúcar de esta
// misma etapa. Y las dos entrevistas llevan además, con todas las letras,
// el aviso de que el encuentro nunca ocurrió, porque una hoja se fotocopia
// y viaja sola, y sin el aviso alguien acabaría citando como real una
// conversación que la casa inventó.
const LECTURAS_IMPR={
  borges:{titulo:'Las píldoras del cometa',tipo:'Cuento, a la manera de Jorge Luis Borges'},
  cervantes:{titulo:'Donde se cuenta lo del cometa con cola, y del buhonero que vendía el remedio',tipo:'Capítulo, a la manera de Miguel de Cervantes Saavedra'},
  harari:{titulo:'El impuesto más antiguo del mundo',tipo:'Ensayo, a la manera de Yuval Noah Harari'},
  entrevista:{titulo:'El poeta que no quiso asustar a nadie',tipo:'Entrevista imaginada con Lucrecio, a la manera de Joaquín Soler Serrano',ficticia:true},
  gala:{titulo:'Los dos miedos, de madrugada',tipo:'Conversación imaginada: Jesús Quintero y Antonio Gala, El Loco de la Colina',ficticia:true},
};
function _hojaImpresa(titulo,cuerpo,pieExtra){
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${titulo} · Átomos contra el miedo · F.A.R.O.</title><style>
@page{size:letter;margin:16mm 15mm;}
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Georgia,'Times New Roman',serif;font-size:11.5pt;line-height:1.55;color:#111;background:#fff;}
h1{font-family:Arial,Helvetica,sans-serif;font-size:15pt;color:#451a03;margin-bottom:2mm;line-height:1.2;}
.tipo{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;color:#555;margin-bottom:3mm;}
.ruta{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:#92400e;border-bottom:1.5pt solid #92400e;padding-bottom:1.5mm;margin-bottom:3mm;display:flex;justify-content:space-between;gap:6mm;}
.etiqueta{border:1.2pt solid #92400e;background:#fdf3e7;border-radius:2mm;padding:2.5mm 3mm;font-family:Arial,Helvetica,sans-serif;font-size:9pt;line-height:1.4;margin-bottom:4mm;}
.idline{font-family:Arial,Helvetica,sans-serif;font-size:9pt;display:flex;gap:4mm;margin-bottom:3mm;}
.idline span.r{flex:1;border-bottom:0.8pt solid #666;}
p.t{text-align:justify;margin-bottom:2.6mm;text-indent:6mm;}
p.t:first-of-type{text-indent:0;}
h2{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#451a03;margin:4mm 0 2mm;}
.sec{font-family:Arial,Helvetica,sans-serif;font-size:10.5pt;font-weight:700;color:#92400e;background:#fdf3e7;border-left:3pt solid #92400e;padding:1.2mm 2.5mm;margin:4mm 0 2mm;}
.q{font-family:Arial,Helvetica,sans-serif;font-size:10pt;margin:2mm 0 1mm;}
.q .n{font-weight:700;color:#92400e;}
.op{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;margin-left:7mm;}
.ln{border-bottom:0.8pt solid #888;height:6.5mm;}
.ln-alta{border-bottom:0.8pt solid #888;height:9mm;}
.fuente{font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;font-style:italic;}
.pauta{page-break-before:always;}
.pl{font-family:Arial,Helvetica,sans-serif;font-size:9pt;margin-bottom:1.6mm;text-align:justify;}
.pie{border-top:0.8pt solid #999;margin-top:5mm;padding-top:2mm;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;display:flex;justify-content:space-between;gap:6mm;}
</style></head><body>${cuerpo}<div class="pie"><span>🏠 Proyecto Educativo F.A.R.O. · Estudio Mayor</span><span>⚛️ Átomos contra el miedo${pieExtra||''}</span></div></body></html>`;
}
function _abreImpresion(doc){
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}
function _etiquetaLectura(meta){
  // La etiqueta base declara el pastiche; la de las entrevistas dice además
  // que el encuentro nunca ocurrió, porque el género lo exige (norma 5-quinquies).
  // En las hojas con dos voces (la entrevista y la conversación) el sujeto va
  // en plural: «ese autor» chirriaba junto a la línea de tipo, que ahí nombra
  // a más de una persona.
  const sujeto=meta.ficticia?'NO es obra de esas personas':'NO es obra de ese autor';
  const voces=meta.ficticia?'imitando sus voces':'imitando su voz';
  const base='<strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>'+sujeto+'</strong>: lo escribió el Proyecto Educativo F.A.R.O. '+voces+', y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.';
  const ficticia=' <strong>El encuentro nunca ocurrió:</strong> las personas son reales, sus obras y sus fechas son reales, y lo único inventado es la conversación que la casa les presta, al modo de las viejas «entrevistas imposibles» de la radio.';
  return '<div class="etiqueta">'+base+(meta.ficticia?ficticia:'')+'</div>';
}
function imprimirLectura(clave){
  const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
  if(!meta||!card){showToast('⚠️ No se encontró la lectura');return;}
  sfx('click');
  const nota=card.querySelector('.lect-nota');
  const parrafos=[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  const cuerpo=`<div class="ruta"><span>⚛️ Ruta de los Átomos y los Ídolos · Etapa 1 de 6</span><span>Lecturas 📖</span></div>`
    +`<h1>${meta.titulo}</h1><div class="tipo">${meta.tipo}</div>`
    +_etiquetaLectura(meta)
    +`<div class="idline"><span>Lee:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
    +parrafos;
  _abreImpresion(_hojaImpresa(meta.titulo,cuerpo,' · '+meta.titulo));
}
function imprimirTodasLasLecturas(){
  sfx('click');
  let cuerpo=`<div class="ruta"><span>⚛️ Ruta de los Átomos y los Ídolos · Etapa 1 de 6</span><span>Las cinco lecturas 📖</span></div>`
    +`<h1>Las cinco lecturas de «Átomos contra el miedo»</h1><div class="tipo">Un cuento, un capítulo de venta, un ensayo, una entrevista imposible y una conversación de madrugada, sobre el mismo remedio</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicios de estilo de la casa, en homenaje.</strong> Los cinco textos <strong>NO son obra de Jorge Luis Borges, de Miguel de Cervantes Saavedra, de Yuval Noah Harari, de Joaquín Soler Serrano ni de Jesús Quintero y Antonio Gala</strong>: los escribió el Proyecto Educativo F.A.R.O. imitando sus voces, y se declaran como pastiche. Las dos entrevistas son <strong>encuentros que nunca ocurrieron</strong>: las personas son reales, y lo único inventado es la conversación. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro de los textos es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  ['borges','cervantes','harari','entrevista','gala'].forEach((clave,i)=>{
    const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
    if(!card)return;
    const nota=card.querySelector('.lect-nota');
    cuerpo+=(i?'<div style="page-break-before:always;"></div>':'')
      +`<h2>${i+1}. ${meta.titulo}</h2><div class="tipo">${meta.tipo}</div>`
      +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
      +[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  });
  _abreImpresion(_hojaImpresa('Las cinco lecturas',cuerpo,' · Las cinco lecturas'));
}
function imprimirPreguntasLecturas(){
  sfx('click');
  const lineas=(n,alta)=>Array(n).fill('<div class="'+(alta?'ln-alta':'ln')+'"></div>').join('');
  let cuerpo=`<div class="ruta"><span>⚛️ Ruta de los Átomos y los Ídolos · Etapa 1 de 6</span><span>Preguntas de las lecturas 📖</span></div>`
    +`<h1>Preguntas de las cinco lecturas</h1><div class="tipo">Átomos contra el miedo · 25 de comprensión lectora, 10 de completar y 10 de análisis complejo</div>`
    +`<div class="idline"><span>Nombre:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +`<div class="etiqueta">Se responde <strong>con los cinco textos delante</strong>: no es un examen de memoria. Las respuestas de las tres secciones van en la <strong>pauta de la última hoja</strong>, así que se resuelve antes de darle la vuelta. Los cinco textos son <strong>ejercicios de estilo de la casa, no obra de Borges, Cervantes, Harari, Soler Serrano ni Quintero y Gala</strong>, y las dos entrevistas son encuentros que nunca ocurrieron.</div>`;
  cuerpo+='<div class="sec">I. Comprensión lectora (25 preguntas)</div>';
  lectComprensionBank.forEach((q,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${q.q} <span class="fuente">(${q.t})</span></div>`;
    q.o.forEach(o=>{cuerpo+=`<div class="op">${o}</div>`;});
  });
  cuerpo+='<div class="sec">II. Completa la oración (10 preguntas)</div>';
  lectCompletarBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q.replace('___','_______________')} <span class="fuente">(${d.t})</span></div>`;
  });
  cuerpo+='<div class="sec">III. Análisis complejo (10 preguntas)</div>';
  lectAnalisisBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q}</div>`+lineas(3,true);
  });
  cuerpo+='<div class="pauta"><div class="sec">✅ Pauta completa de respuestas</div>';
  cuerpo+='<div class="pl"><strong>I. Comprensión lectora:</strong> '+lectComprensionBank.map((q,i)=>(i+1)+') '+'abcd'[q.c]).join(' · ')+'</div>';
  cuerpo+='<div class="pl"><strong>II. Completar:</strong> '+lectCompletarBank.map((d,i)=>(i+1)+') '+d.a).join(' · ')+'</div>';
  cuerpo+='<div class="pl" style="margin-top:2mm;"><strong>III. Análisis complejo (guías de corrección):</strong></div>';
  lectAnalisisBank.forEach((d,i)=>{cuerpo+=`<div class="pl"><strong>${i+1}.</strong> ${d.guia}</div>`;});
  cuerpo+='</div>';
  _abreImpresion(_hojaImpresa('Preguntas de las lecturas',cuerpo,' · Preguntas de las lecturas'));
}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue preguntando de qué está hecho!','¡Muy buen trabajo!','¡Aprendiz del Jardín!','¡Ya distingues el pan del anzuelo!','¡Desmontador de miedos!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='⚛️ ¡'+name+' completó la Etapa 1 de la Ruta de los Átomos y los Ídolos (Átomos contra el miedo)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

